/**
 * Origin helpers. Dependency free so the gate can import this file directly
 * (node --experimental-transform-types) and check the browser side rules:
 * the OIDC callback is produced by the browser, and binding is only offered on a
 * secure origin.
 */

export const API_PREFIX = '/api/v1';

/** Absolute URL for browser navigations that must leave the SPA (OIDC). */
export function absolute(path: string): string {
  return new URL(API_PREFIX + path, window.location.origin).toString();
}

/**
 * The OIDC callback is generated by the browser, never by the server: the admin
 * copies this exact value into the identity provider.
 */
export function oidcCallbackURL(): string {
  return absolute('/auth/oidc/callback');
}

/** The browser only offers SSO binding when the origin is https (or loopback). */
export function isSecureOrigin(): boolean {
  const { protocol, hostname } = window.location;
  if (protocol === 'https:') return true;
  return hostname === 'localhost' || hostname === '127.0.0.1' || hostname === '[::1]';
}
